 11→// V2GitStore provides checkpoint storage operations for the v2 ref layout.
 12→// It writes to two custom refs under refs/entire/:
 13→//   - /main: permanent metadata + compact transcripts
 14→//   - /full/current: active generation of raw transcripts
 15→//
 16→// V2GitStore is separate from GitStore (v1) to keep concerns isolated
 17→// and simplify future v1 removal. It composes GitStore internally to
 18→// reuse ref-agnostic entry-building helpers (tree surgery, session
 19→// indexing, summary aggregation).
 20→type V2GitStore struct {
 21→	repo *git.Repository
 22→	gs   *GitStore // shared entry-building helpers (same package)
 23→
 24→	// maxCheckpointsPerGeneration overrides the rotation threshold for testing.
 25→	// Zero means use DefaultMaxCheckpointsPerGeneration.
 26→	maxCheckpointsPerGeneration int
 27→}
 28→
 29→// maxCheckpoints returns the effective rotation threshold.
 30→func (s *V2GitStore) maxCheckpoints() int {
 31→	if s.maxCheckpointsPerGeneration > 0 {
 32→		return s.maxCheckpointsPerGeneration
 33→	}
 34→	return DefaultMaxCheckpointsPerGeneration
 35→}
 36→
 37→// NewV2GitStore creates a new v2 checkpoint store backed by the given git repository.
 38→func NewV2GitStore(repo *git.Repository) *V2GitStore {
 39→	return &V2GitStore{
 40→		repo: repo,
 41→		gs:   &GitStore{repo: repo},
 42→	}
 43→}
 44→
 45→// ensureRef ensures that a custom ref exists, creating an orphan commit
 46→// with an empty tree if it does not.
 47→func (s *V2GitStore) ensureRef(refName plumbing.ReferenceName) error {
 48→	_, err := s.repo.Reference(refName, true)
 49→	if err == nil {
 50→		return nil // Already exists
 51→	}
 52→
 53→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
 54→	if err != nil {
 55→		return fmt.Errorf("failed to build empty tree: %w", err)
 56→	}
 57→
 58→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
 59→	commitHash, err := CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize v2 ref", authorName, authorEmail)
 60→	if err != nil {
 61→		return fmt.Errorf("failed to create initial commit: %w", err)
 62→	}
 63→
 64→	ref := plumbing.NewHashReference(refName, commitHash)
 65→	if err := s.repo.Storer.SetReference(ref); err != nil {
 66→		return fmt.Errorf("failed to set ref %s: %w", refName, err)
 67→	}
 68→
 69→	return nil
 70→}
 71→
 72→// getRefState returns the parent commit hash and root tree hash for a ref.
 73→func (s *V2GitStore) getRefState(refName plumbing.ReferenceName) (parentHash, treeHash plumbing.Hash, err error) {
 74→	ref, err := s.repo.Reference(refName, true)
 75→	if err != nil {
 76→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
 77→	}
 78→
 79→	commit, err := s.repo.CommitObject(ref.Hash())
 80→	if err != nil {
 81→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit for ref %s: %w", refName, err)
 82→	}
 83→
 84→	return ref.Hash(), commit.TreeHash, nil
 85→}
 86→
 87→// updateRef creates a new commit on a ref with the given tree, updating the ref to point to it.
 88→func (s *V2GitStore) updateRef(refName plumbing.ReferenceName, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) error {
 89→	commitHash, err := CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
 90→	if err != nil {
 91→		return fmt.Errorf("failed to create commit: %w", err)
 92→	}
 93→
 94→	ref := plumbing.NewHashReference(refName, commitHash)
 95→	if err := s.repo.Storer.SetReference(ref); err != nil {
 96→		return fmt.Errorf("failed to update ref %s: %w", refName, err)
 97→	}
 98→
 99→	return nil
100→}
