200→// writeCommittedMain writes metadata entries to the /main ref.
201→// This includes session metadata and prompts — but NOT the raw transcript
202→// (full.jsonl) or content hash (content_hash.txt), which go to /full/current.
203→// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
204→func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
205→	refName := plumbing.ReferenceName(paths.V2MainRefName)
206→	if err := s.ensureRef(refName); err != nil {
207→		return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
208→	}
209→
210→	parentHash, rootTreeHash, err := s.getRefState(refName)
211→	if err != nil {
212→		return 0, err
213→	}
214→
215→	basePath := opts.CheckpointID.Path() + "/"
216→	checkpointPath := opts.CheckpointID.Path()
217→
218→	// Read existing entries at this checkpoint's shard path
219→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
220→	if err != nil {
221→		return 0, err
222→	}
223→
224→	// Build main session entries (metadata, prompts — no transcript or content hash)
225→	sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
226→	if err != nil {
227→		return 0, err
228→	}
229→
230→	// Splice entries into root tree
231→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
232→	if err != nil {
233→		return 0, err
234→	}
235→
236→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
237→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
238→		return 0, err
239→	}
240→	return sessionIndex, nil
241→}
242→
243→// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
244→// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
245→// Returns the session index used, for coordination with writeCommittedFullTranscript.
246→func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
247→	// Read existing summary to get current session count
248→	var existingSummary *CheckpointSummary
249→	metadataPath := basePath + paths.MetadataFileName
250→	if entry, exists := entries[metadataPath]; exists {
251→		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
252→		if err == nil {
253→			existingSummary = existing
254→		}
255→	}
256→
257→	// Determine session index
258→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
259→
260→	// Write session files (metadata and prompts — no transcript or content hash)
261→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
262→	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
263→	if err != nil {
264→		return 0, err
265→	}
266→
267→	// Build the sessions array
268→	var sessions []SessionFilePaths
269→	if existingSummary != nil {
270→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
271→		copy(sessions, existingSummary.Sessions)
272→	} else {
273→		sessions = make([]SessionFilePaths, 1)
274→	}
275→	sessions[sessionIndex] = sessionFilePaths
276→
277→	// Write root CheckpointSummary
278→	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
279→		return 0, err
280→	}
281→	return sessionIndex, nil
282→}
283→
284→// writeMainSessionToSubdirectory writes a single session's metadata and prompts
285→// to a session subdirectory (0/, 1/, 2/, … indexed by session order within the
286→// checkpoint). Unlike the v1 equivalent, this does NOT write the raw transcript
287→// (full.jsonl) or content hash (content_hash.txt) — those go to /full/current.
288→func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
289→	filePaths := SessionFilePaths{}
290→
291→	// Clear existing entries at this session path
292→	for key := range entries {
293→		if strings.HasPrefix(key, sessionPath) {
294→			delete(entries, key)
295→		}
296→	}
297→
298→	// Write prompts
299→	if len(opts.Prompts) > 0 {
300→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
301→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
302→		if err != nil {
303→			return filePaths, err
304→		}
305→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
306→			Name: sessionPath + paths.PromptFileName,
307→			Mode: filemode.Regular,
308→			Hash: blobHash,
309→		}
310→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
311→	}
312→
313→	// Write session metadata
314→	sessionMetadata := CommittedMetadata{
315→		CheckpointID:                opts.CheckpointID,
316→		SessionID:                   opts.SessionID,
317→		Strategy:                    opts.Strategy,
318→		CreatedAt:                   time.Now().UTC(),
319→		Branch:                      opts.Branch,
320→		CheckpointsCount:            opts.CheckpointsCount,
321→		FilesTouched:                opts.FilesTouched,
322→		Agent:                       opts.Agent,
323→		Model:                       opts.Model,
324→		TurnID:                      opts.TurnID,
325→		IsTask:                      opts.IsTask,
326→		ToolUseID:                   opts.ToolUseID,
327→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
328→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
329→		TokenUsage:                  opts.TokenUsage,
330→		SessionMetrics:              opts.SessionMetrics,
331→		InitialAttribution:          opts.InitialAttribution,
332→		Summary:                     redactSummary(opts.Summary),
333→		CLIVersion:                  versioninfo.Version,
334→	}
335→
336→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
337→	if err != nil {
338→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
339→	}
340→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
341→	if err != nil {
342→		return filePaths, err
343→	}
344→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
345→		Name: sessionPath + paths.MetadataFileName,
346→		Mode: filemode.Regular,
347→		Hash: metadataHash,
348→	}
349→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
350→
351→	return filePaths, nil
352→}
353→
354→// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
355→func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
356→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
357→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
358→	if err != nil {
359→		return err
360→	}
361→	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
362→		Name: sessionPath + paths.ContentHashFileName,
363→		Mode: filemode.Regular,
364→		Hash: hashBlob,
365→	}
366→	return nil
367→}
368→
369→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
370→// Transcripts accumulate across checkpoints — each write splices into the existing
371→// tree. Generation metadata (generation.json) at the tree root is updated on every
372→// write with the new checkpoint ID and timestamps.
373→//
374→// sessionIndex is the session slot (0-based), determined by the caller to stay
375→// consistent with the /main ref's session numbering.
376→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
377→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
378→	transcript := opts.Transcript
379→	if len(transcript) == 0 && opts.TranscriptPath != "" {
380→		var readErr error
381→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
382→		if readErr != nil {
383→			transcript = nil
384→		}
385→	}
386→	if len(transcript) == 0 {
387→		return nil // No transcript to write
388→	}
389→
390→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
391→	if err := s.ensureRef(refName); err != nil {
392→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
393→	}
394→
395→	parentHash, rootTreeHash, err := s.getRefState(refName)
396→	if err != nil {
397→		return err
398→	}
399→
400→	basePath := opts.CheckpointID.Path() + "/"
401→	checkpointPath := opts.CheckpointID.Path()
402→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
403→
404→	// Read existing entries at this checkpoint's shard path
405→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
406→	if err != nil {
407→		return err
408→	}
409→
410→	// Clear existing entries at this session path before writing new ones
411→	for key := range entries {
412→		if strings.HasPrefix(key, sessionPath) {
413→			delete(entries, key)
414→		}
415→	}
416→
417→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
418→	if err != nil {
419→		return err
420→	}
421→
422→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
423→		return err
424→	}
425→
426→	// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
427→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
428→	if err != nil {
429→		return err
430→	}
431→
432→	// Update generation.json at the tree root with the new checkpoint ID and timestamps.
433→	// This reads from the pre-splice root tree (to get existing metadata) and writes
434→	// into the post-splice tree (which already has the shard directories).
435→	gen, err := s.updateGenerationForWrite(rootTreeHash, opts.CheckpointID, time.Now().UTC())
436→	if err != nil {
437→		return fmt.Errorf("failed to update generation metadata: %w", err)
438→	}
439→	newTreeHash, err = s.addGenerationToRootTree(newTreeHash, gen)
440→	if err != nil {
441→		return fmt.Errorf("failed to add generation.json to tree: %w", err)
442→	}
443→
444→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
445→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
446→		return err
447→	}
448→
449→	// Check if rotation is needed after successful write.
450→	if len(gen.Checkpoints) >= s.maxCheckpoints() {
451→		if rotErr := s.rotateGeneration(ctx); rotErr != nil {
452→			logging.Warn(ctx, "generation rotation failed",
453→				slog.String("error", rotErr.Error()),
454→				slog.Int("checkpoint_count", len(gen.Checkpoints)),
455→			)
456→			// Non-fatal: rotation failure doesn't invalidate the write
457→		}
458→	}
459→
460→	return nil
461→}
462→
463→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
464→// Returns the redacted transcript bytes so the caller can compute the content hash.
465→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
466→	// Redact secrets before chunking
467→	redacted, err := redact.JSONLBytes(transcript)
468→	if err != nil {
469→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
470→	}
471→
