 88→// readGenerationFromRef reads generation.json from the tree pointed to by the given ref.
 89→func (s *V2GitStore) readGenerationFromRef(refName plumbing.ReferenceName) (GenerationMetadata, error) {
 90→	_, treeHash, err := s.getRefState(refName)
 91→	if err != nil {
 92→		return GenerationMetadata{}, fmt.Errorf("failed to get ref state: %w", err)
 93→	}
