 99→func (s *V2GitStore) marshalGenerationBlob(gen GenerationMetadata) (object.TreeEntry, error) {
100→	data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
101→	if err != nil {
102→		return object.TreeEntry{}, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
103→	}
104→
105→	blobHash, err := CreateBlobFromContent(s.repo, data)
106→	if err != nil {
107→		return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
108→	}
109→
110→	return object.TreeEntry{
111→		Name: paths.GenerationFileName,
112→		Mode: filemode.Regular,
113→		Hash: blobHash,
114→	}, nil
115→}
