117→// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
118→func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
119→	entry, err := s.marshalGenerationBlob(gen)
120→	if err != nil {
