127→// updateGenerationForWrite reads the current generation metadata, appends the
128→// checkpoint ID (if not already present), and updates timestamps.
129→// Returns the updated metadata for the caller to write into the tree.
130→func (s *V2GitStore) updateGenerationForWrite(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, now time.Time) (GenerationMetadata, error) {
131→	gen, err := s.readGeneration(rootTreeHash)
132→	if err != nil {
133→		return GenerationMetadata{}, err
134→	}
135→
136→	// Only append if checkpoint ID is not already present (multi-session writes
137→	// to the same checkpoint should not duplicate the ID).
138→	found := false
139→	for _, existing := range gen.Checkpoints {
140→		if existing == checkpointID {
141→			found = true
142→			break
143→		}
144→	}
145→	if !found {
146→		gen.Checkpoints = append(gen.Checkpoints, checkpointID)
147→
148→		// Only update timestamps when a new checkpoint is added, so they reflect
149→		// checkpoint creation times rather than last-write times.
150→		if gen.OldestCheckpointAt.IsZero() {
151→			gen.OldestCheckpointAt = now
152→		}
153→		gen.NewestCheckpointAt = now
154→	}
155→
156→	return gen, nil
157→}
