161→func (s *V2GitStore) addGenerationToRootTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
162→	entry, err := s.marshalGenerationBlob(gen)
163→	if err != nil {
164→		return plumbing.ZeroHash, err
165→	}
166→
167→	return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
