 24→// DefaultMaxCheckpointsPerGeneration is the rotation threshold.
 25→// When a generation reaches this many checkpoints, it is archived
 26→// and a fresh /full/current is created.
 27→const DefaultMaxCheckpointsPerGeneration = 100
 28→
 29→// GenerationMetadata tracks the state of a /full/* generation.
 30→// A "generation" is a batch of raw transcripts stored under a single ref.
 31→// The active generation lives at /full/current; when it reaches the checkpoint
 32→// limit, it is archived as a numbered ref (e.g., /full/0000000000001) and a
 33→// fresh /full/current is created. Archived generations can later be cleaned up
 34→// based on their timestamps (see RFD-009 cleanup path).
 35→//
 36→// Stored at the tree root as generation.json and updated on every WriteCommitted.
 37→// UpdateCommitted (stop-time finalization) does NOT update this file since it
 38→// replaces an existing transcript rather than adding a new checkpoint.
 39→//
 40→// The generation's sequence number is derived from the ref name, not stored
 41→// in this struct. The checkpoint count is len(Checkpoints).
 42→type GenerationMetadata struct {
 43→	// Checkpoints is the list of checkpoint IDs stored in this generation.
 44→	// Used for finding which generation holds a specific checkpoint
 45→	// without walking the tree. len(Checkpoints) gives the count.
 46→	Checkpoints []id.CheckpointID `json:"checkpoints"`
 47→
 48→	// OldestCheckpointAt is the creation time of the earliest checkpoint.
 49→	OldestCheckpointAt time.Time `json:"oldest_checkpoint_at"`
 50→
 51→	// NewestCheckpointAt is the creation time of the most recent checkpoint.
 52→	NewestCheckpointAt time.Time `json:"newest_checkpoint_at"`
 53→}
