 55→// readGeneration reads generation.json from the given tree hash.
 56→// Returns a zero-value GenerationMetadata if the file doesn't exist (new/empty generation).
 57→func (s *V2GitStore) readGeneration(treeHash plumbing.Hash) (GenerationMetadata, error) {
 58→	if treeHash == plumbing.ZeroHash {
 59→		return GenerationMetadata{}, nil
 60→	}
 61→
 62→	tree, err := s.repo.TreeObject(treeHash)
 63→	if err != nil {
 64→		return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
 65→	}
 66→
 67→	file, err := tree.File(paths.GenerationFileName)
 68→	if err != nil {
 69→		if errors.Is(err, object.ErrFileNotFound) || errors.Is(err, object.ErrEntryNotFound) {
 70→			return GenerationMetadata{}, nil
 71→		}
 72→		return GenerationMetadata{}, fmt.Errorf("failed to find %s in tree: %w", paths.GenerationFileName, err)
 73→	}
 74→
 75→	content, err := file.Contents()
 76→	if err != nil {
 77→		return GenerationMetadata{}, fmt.Errorf("failed to read %s: %w", paths.GenerationFileName, err)
 78→	}
 79→
 80→	var gen GenerationMetadata
 81→	if err := json.Unmarshal([]byte(content), &gen); err != nil {
 82→		return GenerationMetadata{}, fmt.Errorf("failed to parse %s: %w", paths.GenerationFileName, err)
 83→	}
 84→
 85→	return gen, nil
 86→}
