 21→// ReadCommitted reads the checkpoint summary from the v2 /main ref.
 22→// Returns nil, nil if the checkpoint doesn't exist (same contract as GitStore.ReadCommitted).
 23→func (s *V2GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
 24→	if err := ctx.Err(); err != nil {
 25→		return nil, err //nolint:wrapcheck // Propagating context cancellation
 26→	}
 27→
 28→	refName := plumbing.ReferenceName(paths.V2MainRefName)
 29→	_, rootTreeHash, err := s.getRefState(refName)
 30→	if err != nil {
 31→		return nil, nil //nolint:nilnil,nilerr // Ref doesn't exist means no checkpoint
 32→	}
 33→
 34→	rootTree, err := s.repo.TreeObject(rootTreeHash)
 35→	if err != nil {
 36→		return nil, nil //nolint:nilnil,nilerr // Tree not readable
 37→	}
 38→
 39→	cpTree, err := rootTree.Tree(checkpointID.Path())
 40→	if err != nil {
 41→		return nil, nil //nolint:nilnil,nilerr // Checkpoint subtree not found
 42→	}
 43→
 44→	metadataFile, err := cpTree.File(paths.MetadataFileName)
 45→	if err != nil {
 46→		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
 47→	}
 48→
 49→	content, err := metadataFile.Contents()
 50→	if err != nil {
 51→		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
 52→	}
 53→
 54→	var summary CheckpointSummary
 55→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
 56→		return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
 57→	}
 58→
 59→	return &summary, nil
 60→}
