 62→// ReadSessionContent reads a session's metadata and prompts from the v2 /main ref,
 63→// and the raw transcript (full.jsonl) from /full/* refs (current + archived generations).
 64→// This is the v2 equivalent of GitStore.ReadSessionContent — it reads the raw agent
 65→// transcript, not the compact transcript.jsonl. Used by resume and RestoreLogsOnly.
 66→// Returns ErrNoTranscript if the session exists but no raw transcript is available.
 67→// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
 68→func (s *V2GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
 69→	if err := ctx.Err(); err != nil {
 70→		return nil, err //nolint:wrapcheck // Propagating context cancellation
 71→	}
 72→
 73→	refName := plumbing.ReferenceName(paths.V2MainRefName)
 74→	_, rootTreeHash, err := s.getRefState(refName)
 75→	if err != nil {
 76→		return nil, ErrCheckpointNotFound
 77→	}
 78→
 79→	rootTree, err := s.repo.TreeObject(rootTreeHash)
 80→	if err != nil {
 81→		return nil, ErrCheckpointNotFound
 82→	}
 83→
 84→	cpTree, err := rootTree.Tree(checkpointID.Path())
 85→	if err != nil {
 86→		return nil, ErrCheckpointNotFound
 87→	}
 88→
 89→	sessionDir := strconv.Itoa(sessionIndex)
 90→	sessionTree, err := cpTree.Tree(sessionDir)
 91→	if err != nil {
 92→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
 93→	}
 94→
 95→	result := &SessionContent{}
 96→
 97→	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
 98→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
 99→			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
100→				return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
101→			}
102→		}
103→	}
104→
105→	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
106→		if content, contentErr := file.Contents(); contentErr == nil {
107→			result.Prompts = content
108→		}
109→	}
110→
111→	transcript, transcriptErr := s.readTranscriptFromFullRefs(ctx, checkpointID, sessionIndex, result.Metadata.Agent)
112→	if transcriptErr != nil {
113→		logging.Debug(ctx, "v2 raw transcript read failed",
114→			slog.String("checkpoint_id", string(checkpointID)),
115→			slog.Int("session_index", sessionIndex),
116→			slog.String("error", transcriptErr.Error()),
117→		)
118→	}
119→	if len(transcript) == 0 {
120→		return nil, ErrNoTranscript
121→	}
122→	result.Transcript = transcript
123→
124→	return result, nil
125→}
