127→// readTranscriptFromFullRefs reads the raw transcript for a checkpoint session
128→// by searching /full/current first, then archived generations in reverse order.
129→func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, agentType types.AgentType) ([]byte, error) {
130→	if err := ctx.Err(); err != nil {
131→		return nil, err //nolint:wrapcheck // Propagating context cancellation
132→	}
133→
