// computeGenerationTimestamps walks a /full/* tree and reads session metadata
// to determine the oldest and newest checkpoint timestamps.
func (s *V2GitStore) computeGenerationTimestamps(ctx context.Context, treeHash plumbing.Hash) (GenerationMetadata, error) {
	tree, err := s.repo.TreeObject(treeHash)
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
	}

	var oldest, newest time.Time

	for _, shardEntry := range tree.Entries {
		if shardEntry.Mode != filemode.Dir {
			continue
		}
		shardTree, err := s.repo.TreeObject(shardEntry.Hash)
		if err != nil {
			continue
		}
		for _, cpEntry := range shardTree.Entries {
			if cpEntry.Mode != filemode.Dir {
				continue
			}
			cpTree, err := s.repo.TreeObject(cpEntry.Hash)
			if err != nil {
				continue
			}
			// Look for session subdirectory 0/ which has metadata.json
			for _, sessionEntry := range cpTree.Entries {
				if sessionEntry.Mode != filemode.Dir {
					continue
				}
				sessionTree, err := s.repo.TreeObject(sessionEntry.Hash)
				if err != nil {
					continue
				}
				metaFile, err := sessionTree.File(paths.MetadataFileName)
				if err != nil {
					continue
				}
				content, err := metaFile.Contents()
				if err != nil {
					continue
				}
				var meta CommittedMetadata
				if err := json.Unmarshal([]byte(content), &meta); err != nil {
					continue
				}
				if !meta.CreatedAt.IsZero() {
					if oldest.IsZero() || meta.CreatedAt.Before(oldest) {
						oldest = meta.CreatedAt
					}
					if newest.IsZero() || meta.CreatedAt.After(newest) {
						newest = meta.CreatedAt
					}
				}
			}
		}
	}

	return GenerationMetadata{
		OldestCheckpointAt: oldest,
		NewestCheckpointAt: newest,
	}, nil
}

// addGenerationJSONToTree adds generation.json to an existing root tree, returning
// a new root tree hash. Preserves all existing entries (shard directories, etc.).
func (s *V2GitStore) addGenerationJSONToTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
	entry, err := s.marshalGenerationBlob(gen)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
		UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
}
